import java.util.Arrays;

public class Runner {
    record Case(String label, int[] input, int expected) {}

    public static void main(String[] args) {
        Case[] cases = new Case[]{
            new Case("[1, 2, 3, 4, 5]", new int[]{1, 2, 3, 4, 5}, 15),
            new Case("[10]", new int[]{10}, 10),
            new Case("[-1, 1]", new int[]{-1, 1}, 0),
            new Case("[]", new int[]{}, 0)
        };
        for (Case c : cases) {
            try {
                int actual = Solution.sum(c.input);
                if (actual == c.expected) {
                    System.out.println("PASS\t" + c.label);
                } else {
                    System.out.println("FAIL\t" + c.label + "\t" + c.expected + "\t" + actual);
                }
            } catch (Throwable t) {
                System.out.println("ERROR\t" + c.label + "\t" + t.getClass().getSimpleName() + ": " + t.getMessage());
            }
        }
    }
}
